head.script:
scwin.trigger1_onclick = function(e) {
	requires("uiplugin.popup");
	var options1 = {
		id: "popup1",
		type: "litewindow",
		width: "230px",
		height: "250px",
		top: "130px",
		left: "100px",
		popupName: "openPopup1",
		useIFrame: "true",
		closeAction: "test",
		modal: "true"
	};
	$w.openPopup("/sample/common_link/p_pop_w_closePopup_w_getPopup_WEFF-385_(WSQ-3733)_main_pop.xml", options1);
};
scwin.closeLog = [];
scwin.onpageload = function() {
	test = function(id) {
		var pop = $w.getPopup("popup1");
		var win = $w.getPopupWindow("popup1");
		scwin.closeLog.push([id, pop != null, win != null && win !== window]);
		return true;
	};
};
